// haystack filler module 00 — ordinary, needle-free TypeScript.

export interface Widget00 {
  id: string;
  weight: number;
  tags: string[];
}

export function makeWidget00(id: string, weight: number): Widget00 {
  return { id, weight, tags: ["filler", "module-00"] };
}

export function totalWeight00(items: Widget00[]): number {
  let total = 0;
  for (let i = 0; i < items.length; i += 1) {
    total += items[i].weight;
  }
  return total;
}

export function heaviest00(items: Widget00[]): Widget00 | null {
  let best: Widget00 | null = null;
  for (const item of items) {
    if (best === null || item.weight > best.weight) {
      best = item;
    }
  }
  return best;
}

